import numpy as np, pandas as pd, xgboost as xgb
CFG = dict(params=dict(n_estimators=300, max_depth=3, learning_rate=0.05, subsample=0.8, colsample_bytree=0.8, min_child_weight=5),
           native=['state','facility_type_code','air_pollutant_class_code','comp_monitor_type_code','state_epa_flag'],
           te=[], te_m=50.0, te_folds=5, te_mode='block', drop=[], extra=[], recency=0.0, mono=False)
COLS = ['state','epa_region','sic_2digit','naics_2digit','facility_type_code','air_pollutant_class_code','program_count','pollutant_count','comp_monitor_type_code','state_epa_flag','prior_evaluations_3y','days_since_last_evaluation','prior_stack_test_failures_3y','prior_hpv_count','days_since_hpv_resolution','prior_formal_actions_3y','prior_penalties_3y','prior_tv_deviations_3y']
STR = ['state','facility_type_code','air_pollutant_class_code','comp_monitor_type_code','state_epa_flag']

def _key(v):
    return 'NA' if v != v or v is None else (v if isinstance(v, str) else float(v))

def _te_tables(rows, y, keys):
    t = {}
    for r, yy in zip(rows, y):
        k = tuple(_key(r[c]) for c in keys)
        a = t.get(k)
        if a is None: t[k] = [yy, 1]
        else: a[0] += yy; a[1] += 1
    return t

def _te_val(t, k, prior, m):
    a = t.get(k)
    return prior if a is None else (a[0] + m * prior) / (a[1] + m)

def fit(X_train, y_train, *, seed, threads):
    cfg = CFG
    X = X_train[COLS]
    rows = [dict(zip(COLS, r)) for r in X.to_numpy(dtype=object)]
    y = np.asarray(y_train).astype(int); n = len(y)
    state = {"cfg": cfg}
    state['levels'] = {c: {v: i for i, v in enumerate(sorted({_key(r[c]) for r in rows} - {'NA'}, key=str))} for c in cfg['native']}
    prior = float(y.mean()); state['prior'] = prior
    state['te'] = {}
    for keys in cfg['te']:
        state['te'][tuple(keys)] = _te_tables(rows, y, keys)
    state['te'] = {k: {kk: (v[0], v[1]) for kk, v in t.items()} for k, t in state['te'].items()}
    F = prepare(state, X)
    # out-of-fold target encodings for training rows
    if cfg['te']:
        names = state['names']
        K = cfg['te_folds']
        if cfg['te_mode'] == 'block': fold = (np.arange(n) * K // n)
        else: fold = np.random.RandomState(seed).randint(0, K, n)
        for keys in cfg['te']:
            j = names.index('te_' + '_'.join(keys))
            for f in range(K):
                inn = np.where(fold != f)[0]; out = np.where(fold == f)[0]
                yi = y[inn]; pr = float(yi.mean())
                t = _te_tables([rows[i] for i in inn], yi, keys)
                for i in out:
                    F[i, j] = _te_val(t, tuple(_key(rows[i][c]) for c in keys), pr, cfg['te_m'])
    names = state['names']
    ft = ['c' if nm in cfg['native'] else 'q' for nm in names]
    kw = {}
    if cfg['mono']:
        inc = {'prior_stack_test_failures_3y','prior_hpv_count','prior_formal_actions_3y','prior_tv_deviations_3y','program_count'}
        kw['monotone_constraints'] = tuple(1 if nm in inc else 0 for nm in names)
    w = None
    if cfg['recency']:
        w = np.exp(cfg['recency'] * (np.arange(n) / n - 1.0)); w = w / w.mean()
    m = xgb.XGBClassifier(tree_method="hist", enable_categorical=True, feature_types=ft, random_state=seed, n_jobs=threads, **kw, **cfg['params'])
    m.fit(F, y, sample_weight=w)
    state["model"] = m
    return state

def prepare(state, X):
    cfg = state['cfg']; nan = float('nan')
    cols = list(X.columns); A = X.to_numpy(dtype=object)
    out = []; names = []
    for ri in range(A.shape[0]):
        r = dict(zip(cols, A[ri])); f = []; names = []
        for c in COLS:
            if c in cfg['drop']: continue
            v = r[c]
            if c in cfg['native']:
                f.append(state['levels'][c].get(_key(v), nan))
            elif c in STR:
                continue
            else:
                f.append(nan if v is None else float(v))
            names.append(c)
        for keys, t in state['te'].items():
            f.append(_te_val(t, tuple(_key(r[c]) for c in keys), state['prior'], cfg['te_m'])); names.append('te_' + '_'.join(keys))
        ex = cfg['extra']
        if ex:
            hp = float(r['prior_hpv_count']); d = r['days_since_hpv_resolution']; d = nan if d is None else float(d)
            fa = float(r['prior_formal_actions_3y']); st = float(r['prior_stack_test_failures_3y']); tv = float(r['prior_tv_deviations_3y'])
            pe = float(r['prior_evaluations_3y']); dl = r['days_since_last_evaluation']; dl = nan if dl is None else float(dl)
            pc = float(r['program_count']); po = float(r['pollutant_count']); pen = float(r['prior_penalties_3y'])
            E = {'hpv_rate': hp / (d + 365.0), 'enf_sum': fa + st + tv, 'enf_any': float((fa > 0) + (st > 0) + (tv > 0) + (hp > 0)),
                 'pen_per_action': pen / (fa + 1.0), 'ev_x_gap': dl * (pe + 1.0), 'poll_per_prog': po / pc if pc else nan,
                 'recent_hpv': 1.0 / (d + 30.0) if d == d else 0.0, 'hp_per_eval': hp / (pe + 1.0), 'size': pc + po / 5.0}
            for nm in ex:
                f.append(E[nm]); names.append(nm)
        out.append(f)
    state['names'] = names
    return np.asarray(out, dtype=np.float32)
